// Validacion Estricta de Datos y Tipos (Camino Feliz vs Infeliz)
const body = $json.body || $json;

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const esEmailValido = body.email_cliente && emailRegex.test(body.email_cliente.trim());
const tieneEquipo = body.equipo_industrial && typeof body.equipo_industrial === 'string' && body.equipo_industrial.trim().length > 2;
const tieneMensaje = body.mensaje_requerimiento && typeof body.mensaje_requerimiento === 'string' && body.mensaje_requerimiento.trim().length > 5;
const tieneCliente = body.nombre_cliente && typeof body.nombre_cliente === 'string' && body.nombre_cliente.trim().length > 1;

const esValido = Boolean(esEmailValido && tieneEquipo && tieneMensaje && tieneCliente);

return {
  json: {
    ...body,
    id_solicitud: body.id_solicitud || 'COT-' + new Date().getFullYear() + '-' + Math.floor(1000 + Math.random() * 9000),
    fecha_ingreso: new Date().toISOString(),
    es_valido: esValido,
    motivo_invalido: esValido ? null : 'Faltan campos obligatorios (nombre, email válido, equipo industrial o detalle técnico)'
  }
};

// Gobernanza y Anonimizacion de PII (Proteccion de Datos Industriales)
const raw = $json;

// Desacoplamos los datos sensibles (PII)
const piiData = {
  nombre_cliente: raw.nombre_cliente,
  email_cliente: raw.email_cliente,
  empresa_cliente: raw.empresa_cliente || 'No especificada',
  telefono_cliente: raw.telefono_cliente || 'N/A'
};

const tokenAnonimo = 'CLI-SAN-' + Math.floor(1000 + Math.random() * 9000);

// Payload higienizado para el motor de IA
const aiCleanPayload = {
  id_solicitud: raw.id_solicitud,
  id_cliente_anonimizado: tokenAnonimo,
  equipo_industrial: raw.equipo_industrial,
  linea_produccion: raw.linea_produccion || 'Línea de Envasado Estándar',
  mensaje_requerimiento: raw.mensaje_requerimiento,
  urgencia_dias: raw.urgencia_dias || 15
};

return {
  json: {
    ...aiCleanPayload,
    _pii_vault: piiData
  }
};

