// Re-asociacion PII, Fusion de Datos y Verificacion de Respuesta IA
const aiItem = $json;
const piiData = $('Gobernanza: Anonimización PII').item.json._pii_vault;
const baseData = $('Gobernanza: Anonimización PII').item.json;

// Si la IA fallo por timeout o cuota
if (!aiItem || aiItem.error || !aiItem.message) {
  return {
    json: {
      es_error_ia: true,
      id_solicitud: baseData.id_solicitud,
      error_detalle: aiItem.error ? JSON.stringify(aiItem.error) : 'Respuesta de IA vacía o corrupta',
      pii: piiData
    }
  };
}

let parsedAi = {};
try {
  const contentStr = aiItem.message.content;
  parsedAi = typeof contentStr === 'string' ? JSON.parse(contentStr) : contentStr;
} catch (e) {
  parsedAi = {
    error: 'JSON Parse Error: ' + e.message,
    monto_estimado_total_usd: 0,
    requiere_hitl: true
  };
}

// Calculo de seguridad adicional: regla determinista para HITL
const montoTotal = Number(parsedAi.monto_estimado_total_usd) || 0;
const esHitlObligatorio = montoTotal > 3000 || parsedAi.complejidad_servicio === 'Alta' || parsedAi.categoria_lead === 'VIP' || parsedAi.requiere_hitl === true;

return {
  json: {
    es_error_ia: false,
    id_solicitud: baseData.id_solicitud,
    nombre_cliente: piiData.nombre_cliente,
    email_cliente: piiData.email_cliente,
    empresa_cliente: piiData.empresa_cliente,
    telefono_cliente: piiData.telefono_cliente,
    equipo_industrial: parsedAi.equipo_detectado || baseData.equipo_industrial,
    linea_produccion: parsedAi.linea_produccion || baseData.linea_produccion,
    monto_estimado_total_usd: montoTotal,
    items_cotizacion: parsedAi.items_cotizacion || [],
    tiempo_entrega_dias: parsedAi.tiempo_entrega_dias || 15,
    score_lead: parsedAi.score_lead || 70,
    categoria_lead: parsedAi.categoria_lead || 'Estándar',
    complejidad_servicio: parsedAi.complejidad_servicio || 'Media',
    requiere_hitl: esHitlObligatorio,
    justificacion_hitl: parsedAi.justificacion_hitl || (esHitlObligatorio ? 'Supera umbral de control $3000 USD' : 'Proceso de bajo riesgo'),
    resumen_ejecutivo: parsedAi.resumen_ejecutivo || 'Cotización generada automáticamente',
    borrador_html: parsedAi.borrador_propuesta_tecnica_html || ''
  }
};

